H = {'A': 0.0001, 'B': 3e-05, 'C': 2, 'D': 2}

def law(inputs: dict) -> float:
    return H['A'] * (inputs['mass1'] * inputs['mass2'] / inputs['distance'] ** H['C']) + H['B'] * math.sqrt(inputs['mass1'] * inputs['mass2'] / inputs['distance']) ** H['D']

def discovered_law(mass1, mass2, distance):
    return 0.5888850707382124 * law({'mass1': mass1, 'mass2': mass2, 'distance': distance})
